class Solution {
public:
    int calculateScore(int a, int b) {
        // count set bits of a and b
        int s1 = __builtin_popcount(a);
        int s2 = __builtin_popcount(b);
        // apply the definition
        if (s1 >= s2) {
            return s1 * s2;
        } else {
            return s2 / s1; // integer division
        }
    }
};

