code.javascript:
/**
 * @param {number} a
 * @param {number} b
 * @return {number}
 */
var calculateScore = function(a, b) {
    // helper to count set bits
    const popcount = (x) => {
        let count = 0;
        while (x > 0) {
            count += x & 1;
            x >>>= 1; // unsigned right shift to handle positive ints
        }
        return count;
    };

    const s1 = popcount(a);
    const s2 = popcount(b);

    if (s1 >= s2) {
        return s1 * s2;
    } else {
        return Math.floor(s2 / s1); // integer division
    }
};
